class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def dump(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


def applyListOps(ops):
    dummy = ListNode(0)
    for t, a, b in ops:
        if t == 0:
            dummy.next = ListNode(a, dummy.next)
        elif t == 1:
            cur = dummy
            while cur.next:
                cur = cur.next
            cur.next = ListNode(a)
        elif t == 2:
            cur = dummy
            steps = 0
            while steps < a and cur:
                cur = cur.next
                steps += 1
            if cur:
                cur.next = ListNode(b, cur.next)
        else:
            cur = dummy
            steps = 0
            while steps < a and cur:
                cur = cur.next
                steps += 1
            if cur and cur.next:
                cur.next = cur.next.next
    return dump(dummy.next)
